// Generated by scripts/sync-domain.mjs from app/src/domain. Do not edit.
// Plan engine, ported from recomp.html r19 (05-business-logic §1.4-1.6, §2.1, §2.5, §3, §7.6).
// The web app keeps the active goal, profile and plan in globals; here they are an explicit
// Engine built once per (goal, profile, saved plan) and then asked about days.
import liftsJson from './data/lifts.json' with { type: 'json' };
import namesJson from './data/names.json' with { type: 'json' };
import { addDays, d, diffDays, key, todayKey, trimNum } from './dates.ts';
import type { CheckItem, DayPlan, Goal, Plan, Profile, Slot, UserCheck, Week } from './types.ts';

const LIFTS_DEFAULT = liftsJson as Record<string, string[]>;
const NAMES_DEFAULT = namesJson as Record<string, string>;
const LEGACY_KEYS = ['homeA', 'homeB', 'fullA', 'fullB', 'lowerA', 'upperA', 'lowerB', 'upperB'];

export function provisionalGoal(today = todayKey()): Goal {
  return {
    id: 'g0', provisional: true, name: '', why: '', type: 'recomp', start: today, due: key(addDays(d(today), 83)),
    event: null, trainStart: today, startKg: null, targetKg: null, kcal: 2000, protein: 120, steps: 8000,
    homeFirst: false, done: false, milestones: [],
  };
}

export function phaseBounds(w: number): [number, number][] {
  let b1 = Math.max(1, Math.round(w * 0.235));
  let b2 = Math.max(b1 + 1, Math.round(w * 0.588));
  let b3 = Math.max(b2 + 1, Math.round(w * 0.882));
  if (b3 >= w) b3 = Math.max(b2 + 1, w - 1);
  if (b2 >= b3) b2 = Math.max(b1 + 1, b3 - 1);
  if (b1 >= b2) b1 = Math.max(1, b2 - 1);
  return [[1, b1], [b1 + 1, b2], [b2 + 1, b3], [b3 + 1, w]];
}

export const kcalFloor = (pf: Profile) => +(pf.kcalFloor ?? 0) || (pf.sex === 'female' ? 1200 : pf.sex === 'male' ? 1500 : 1400);
export const proteinFloor = (pf: Profile, g: Goal | null) => +(pf.proteinFloor ?? 0) || Math.round(((g && g.protein) || 120) * 0.85 / 5) * 5;
export const waistWeekday = (pf: Profile) => {
  const w = pf.waistDay;
  return w != null && !Number.isNaN(+w) ? (+w) % 7 : 1;
};

const slotL = (s: string, c: string): Slot => ({ t: 'lift', s, c });
const slotC = (c: string): Slot => ({ t: 'cardio', c });
const slotR = (c: string): Slot => ({ t: 'rest', c });

export type Timeline = {
  START: string; END: string; DEPART: string; TOTAL: number; WEEKS_N: number;
  PHASE_W: [number, number][]; MAINT_W: number;
  TSTART: string; TTOTAL: number; TWEEKS: number; TPHASE_W: [number, number][]; TMAINT_W: number;
  START_KG: number; TARGET_KG: number; PROJ: number[];
  LABS: Record<string, string>; TASKS: Record<string, string>;
};

/** applyGoal(). firstWeightFromStart = first logged weight on or after goal.start (fallback start kg). */
export function buildTimeline(G: Goal, firstWeightFromStart: number | null): Timeline {
  const START = G.start, END = G.due, DEPART = G.event || G.due;
  let START_KG = +(G.startKg ?? 0) || 0;
  if (!START_KG && firstWeightFromStart) START_KG = +firstWeightFromStart;
  const TARGET_KG = +(G.targetKg ?? 0) || START_KG;
  const TOTAL = Math.max(1, diffDays(d(START), d(END)) + 1);
  const WEEKS_N = Math.max(1, Math.ceil(TOTAL / 7));
  const PHASE_W = phaseBounds(WEEKS_N);
  const MAINT_W = Math.max(1, PHASE_W[1][1] - 1);
  const TSTART = G.trainStart || G.start;
  const TTOTAL = Math.max(1, diffDays(d(TSTART), d(END)) + 1);
  const TWEEKS = Math.max(1, Math.ceil(TTOTAL / 7));
  const TPHASE_W = phaseBounds(TWEEKS);
  const TMAINT_W = Math.max(1, TPHASE_W[1][1] - 1);
  // buildProj: first fortnight weighs 1.9x, the maintenance week is flat.
  const drop = START_KG - TARGET_KG, share: number[] = [];
  for (let i = 1; i <= WEEKS_N; i++) share.push(i <= Math.min(2, WEEKS_N) ? 1.9 : i === MAINT_W ? 0 : 1);
  const sum = share.reduce((a, b) => a + b, 0) || 1;
  const PROJ = [START_KG]; let cur = START_KG;
  for (let i = 0; i < WEEKS_N; i++) { cur -= drop * share[i] / sum; PROJ.push(Math.round(cur * 100) / 100); }
  const LABS: Record<string, string> = {}, TASKS: Record<string, string> = {};
  (G.milestones || []).forEach((m) => { if (!m || !m.d) return; if (m.k === 'lab') LABS[m.d] = m.t; else TASKS[m.d] = m.t; });
  return { START, END, DEPART, TOTAL, WEEKS_N, PHASE_W, MAINT_W, TSTART, TTOTAL, TWEEKS, TPHASE_W, TMAINT_W, START_KG, TARGET_KG, PROJ, LABS, TASKS };
}

export function makePlan(G: Goal, PROFILE: Profile, TMAINT_W: number): Plan {
  const equip = PROFILE.equip || 'gym', days = Math.max(2, Math.min(5, +(PROFILE.days ?? 0) || 3));
  const st = G.steps || 8000, kc = G.kcal || 2200;
  const A = equip === 'home' ? 'homeA' : equip === 'body' ? 'bodyA' : 'fullA';
  const B = equip === 'home' ? 'homeB' : equip === 'body' ? 'bodyB' : 'fullB';
  const split = equip === 'gym' && days >= 4;
  const walk = 'Walk 20 to 30 minutes at an easy pace.';
  const after = equip === 'gym' ? '10 to 15 minutes of easy cardio after lifting.' : 'A 10-minute brisk walk after the session.';
  const rest = 'Rest day. A walk if you feel like it.';
  const L = (k: string) => slotL(k, after);
  const lay = (x: string, y: string, hard?: boolean): Week => {
    const extra = days >= 5 ? (hard ? 'Intervals: 8 × (1 min hard / 2 min easy) on a bike, plus 10 min easy.' : 'Your choice: a class, a sport or a long walk.') : walk;
    if (days === 2) return [L(x), slotC(walk), slotC(walk), L(y), slotC(walk), slotC(walk), slotR(rest)];
    if (days === 3) return [L(x), slotC(walk), L(y), slotC(walk), L(x), slotC(walk), slotR(rest)];
    if (split) return [L('lowerA'), L('upperA'), slotC('Zone 2, 30 minutes: bike, incline walk or elliptical.'), L('lowerB'), L('upperB'), slotC(extra), slotR(rest)];
    return [L(x), L(y), slotC(walk), L(x), L(y), slotC(extra), slotR(rest)];
  };
  const used = split ? ['lowerA', 'upperA', 'lowerB', 'upperB'] : [A, B];
  const programs: Plan['programs'] = {};
  used.forEach((k) => { programs[k] = { name: NAMES_DEFAULT[k], kit: k.startsWith('home') ? 'home' : k.startsWith('body') ? 'body' : 'gym', ex: LIFTS_DEFAULT[k].slice() }; });
  const fat = Math.round(kc * 0.28 / 9), pr = G.protein || 120;
  const carb = Math.max(50, Math.round((kc - pr * 4 - fat * 9) / 4)), fib = Math.max(20, Math.round(kc / 1000 * 14));
  const cap = (x: number) => Math.min(15000, x);
  const lose = (G.type || 'lose') === 'lose';
  return {
    v: 1, by: 'default', at: null, note: '', programs, targets: { carb, fat, fiber: fib },
    phases: [
      { name: 'Phase 1 · Base', steps: st, weeks: [lay(A, B), lay(B, A)],
        detail: 'Learn the movements and find your working loads. Stop every set with two or three reps left. The job of this block is a habit that survives a busy week.' },
      { name: 'Phase 2 · Build', steps: cap(st + 1000), weeks: [lay(A, B), lay(B, A)],
        detail: 'Loads climb on double progression: reach the top of the rep range on every set, then add a little weight.' + (lose ? ' Week ' + TMAINT_W + ' is a planned maintenance week at ' + (kc + 500).toLocaleString('en-US') + ' kcal. It is scheduled, not a failure.' : '') },
      { name: 'Phase 3 · Push', steps: cap(st + 1500), weeks: [lay(A, B, true), lay(B, A, true)],
        detail: 'The hardest block. Take the last set of each exercise close to failure, keep your steps up and protect your sleep.' },
      { name: 'Phase 4 · Sharpen', steps: cap(st + 1500), weeks: [lay(A, B), lay(B, A)],
        detail: 'Hold your loads, no new maxes. Sleep more and arrive at the end of the block rested rather than depleted.' },
    ],
  };
}

export function homeFirstPlan(G: Goal, TMAINT_W: number): Plan {
  const home = !!G.homeFirst, kc = G.kcal || 2200, st = G.steps || 8000;
  const n = (x: number) => x.toLocaleString('en-US');
  const programs: Plan['programs'] = {};
  LEGACY_KEYS.forEach((k) => { programs[k] = { name: NAMES_DEFAULT[k], kit: k === 'homeA' || k === 'homeB' ? 'home' : 'gym', ex: LIFTS_DEFAULT[k].slice() }; });
  const full = (h: boolean): Week[] => {
    const A = h ? 'homeA' : 'fullA', B = h ? 'homeB' : 'fullB';
    const after = h ? '20 min brisk walk after the session — outdoors or on the spot.' : '30 min Zone 2 after lifting.';
    const off = h ? '25 min brisk walk. No lifting.' : '30 min Zone 2 walk. No lifting.';
    const rest = 'Rest day. Walk if you feel like it, nothing structured.';
    const wk = (x: string, y: string): Week => [slotL(x, after), slotC(off), slotL(y, after), slotC(off), slotL(x, after), slotC(off), slotR(rest)];
    return [wk(A, B), wk(B, A)];
  };
  const split = (z: string, p3: boolean): Week[] => {
    const after = '15 min easy walk after lifting. Save the long Zone 2 for tomorrow.';
    const w: Week = [slotL('lowerA', after), slotL('upperA', after), slotC(z + ' min Zone 2 (bike, elliptical or incline treadmill).'),
      slotL('lowerB', after), slotL('upperB', after),
      slotC(p3 ? 'Intervals: 8 × (1 min hard / 2 min easy) on the bike, plus 10 min easy.' : z + ' min Zone 2.'),
      slotR('Rest day. Hit your step target, nothing structured.')];
    return [w, JSON.parse(JSON.stringify(w))];
  };
  return {
    v: 1, by: 'default', at: null, note: '', programs, targets: { carb: 200, fat: 65, fiber: 33 },
    phases: [
      { name: 'Phase 1 · ' + (home ? 'Home base' : 'Base'), steps: st, weeks: full(home),
        detail: home
          ? 'Three full-body sessions a week at home with dumbbells, bands and a chair. Walking builds toward ' + n(st) + ' steps. The job of this block is joint tolerance and a habit that survives a bad work week, not weight on the bar.'
          : 'Three full-body sessions a week at the gym, deliberately light. Zone 2 cardio and ' + n(st) + ' steps. The job of this block is to re-establish the habit and find your working loads without wrecking the first fortnight.' },
      { name: 'Phase 2 · Build', steps: st + 1000, weeks: split('30–35', false),
        detail: 'Four sessions on an upper/lower split, Zone 2 three times a week at 30 to 35 minutes, steps to ' + n(st + 1000) + '. Loads climb on double progression. Week ' + TMAINT_W + ' is a deliberate maintenance week at ' + n(kc + 500) + ' kcal. It is not a failure week, it is scheduled.' },
      { name: 'Phase 3 · Push', steps: st + 2000, weeks: split('40–45', true),
        detail: 'Same four-day split with a weekly interval session added, Zone 2 out to 40 to 45 minutes, steps to ' + n(st + 2000) + '. This is the block where the visible change happens, and the one where sleep and adherence usually slip.' },
      { name: 'Phase 4 · Sharpen', steps: st + 2000, weeks: full(false),
        detail: 'Back to three full-body sessions at Phase 2 loads. No new personal bests, no new stimulus, no last-minute crash dieting. Calories hold at ' + n(kc) + ', sleep goes to eight hours, water and salt stay steady. The point is to arrive recovered rather than depleted.' },
    ],
  };
}

/** Validator for anything loaded from storage or returned by Claude. null = refused. */
/** r19 defaultPlan(): home-first goals get the home-first layout. */
export const defaultPlanFor = (G: Goal, PROFILE: Profile, TMAINT_W: number) => (G.homeFirst ? homeFirstPlan(G, TMAINT_W) : makePlan(G, PROFILE, TMAINT_W));

export function normPlan(x: unknown): Plan | null {
  const o = x as Record<string, any>;
  if (!o || typeof o !== 'object' || !o.programs || typeof o.programs !== 'object' || !Array.isArray(o.phases) || o.phases.length !== 4) return null;
  const progs: Plan['programs'] = {};
  Object.keys(o.programs).slice(0, 16).forEach((k) => {
    const pr = o.programs[k]; if (!pr || !Array.isArray(pr.ex)) return;
    const kk = String(k).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 24); if (!kk) return;
    const ex = (pr.ex as unknown[]).map((l) => {
      const q = String(l || '').split('|');
      const nm = (q[0] || '').trim().slice(0, 90), sch = (q[1] || '').trim().replace(/(\d)\s*[xX*]\s*(\d)/, '$1 × $2').slice(0, 30);
      const cue = (q.slice(2).join(' ') || '').trim().slice(0, 400);
      if (!nm || !/\d/.test(sch)) return null;
      return nm + '|' + sch + '|' + cue;
    }).filter((v): v is string => !!v).slice(0, 12);
    if (!ex.length) return;
    progs[kk] = { name: String(pr.name || kk).slice(0, 40), kit: pr.kit === 'home' || pr.kit === 'body' ? pr.kit : 'gym', ex };
  });
  if (!Object.keys(progs).length) return null;
  const phases: Plan['phases'] = [];
  for (let i = 0; i < 4; i++) {
    const ph = o.phases[i];
    if (!ph || !Array.isArray(ph.weeks) || !ph.weeks.length) return null;
    const weeks = (ph.weeks as unknown[]).slice(0, 2).map((w) => {
      if (!Array.isArray(w) || w.length !== 7) return null;
      return w.map((sl0): Slot => {
        const sl = (sl0 || {}) as Record<string, any>; const c = String(sl.c || '').slice(0, 220);
        if (sl.t === 'lift' && progs[sl.s]) return { t: 'lift', s: sl.s, c };
        if (sl.t === 'rest') return { t: 'rest', c: c || 'Rest day.' };
        return { t: 'cardio', c: c || 'Walk at an easy pace.' };
      });
    });
    if (weeks.some((w) => !w)) return null;
    phases.push({ name: String(ph.name || 'Phase ' + (i + 1)).slice(0, 40), detail: String(ph.detail || '').slice(0, 700),
      steps: Math.max(2000, Math.min(30000, Math.round(+ph.steps || 8000))), weeks: weeks as Week[] });
  }
  const t = o.targets || {};
  const cl = (v: unknown, lo: number, hi: number, dflt: number) => { const n = +(v as number); return n >= lo && n <= hi ? Math.round(n) : dflt; };
  return { v: 1, by: o.by === 'claude' || o.by === 'you' ? o.by : 'default', at: +o.at || null, note: String(o.note || '').slice(0, 140),
    programs: progs, phases, targets: { carb: cl(t.carb, 50, 500, 200), fat: cl(t.fat, 20, 200, 65), fiber: cl(t.fiber, 10, 80, 33) } };
}

const WHEN_RANK: Record<string, number> = { waking: 0, morning: 1, breakfast: 2, 'all day': 3, meals: 4, daytime: 5, lunch: 6, afternoon: 7, session: 8, after: 9,
  anytime: 10, evening: 11, dinner: 12, bedtime: 13, night: 14 };
const whenRank = (w: string) => { const r = WHEN_RANK[String(w || '').trim().toLowerCase()]; return r == null ? 10 : r; };

export type Engine = ReturnType<typeof makeEngine>;

export function makeEngine(G: Goal, PROFILE: Profile, savedPlan: Plan | null, firstWeightFromStart: number | null) {
  const T = buildTimeline(G, firstWeightFromStart);
  const PL = savedPlan || (G.homeFirst ? homeFirstPlan(G, T.TMAINT_W) : makePlan(G, PROFILE, T.TMAINT_W));
  const LIFTS: Record<string, string[]> = {}, NAMES: Record<string, string> = {};
  Object.keys(PL.programs).forEach((k) => { LIFTS[k] = PL.programs[k].ex; NAMES[k] = PL.programs[k].name; });
  const ww = waistWeekday(PROFILE);

  function plan(k: string): DayPlan {
    const idx = diffDays(d(T.TSTART), d(k));
    const inRange = idx >= 0 && idx < T.TTOTAL;
    const wk = inRange ? Math.floor(idx / 7) + 1 : idx < 0 ? 0 : T.TWEEKS + 1;
    const dow = ((idx % 7) + 7) % 7;
    let phase = idx < 0 ? 1 : 4;
    for (let pi = 0; pi < T.TPHASE_W.length; pi++) { if (wk >= T.TPHASE_W[pi][0] && wk <= T.TPHASE_W[pi][1]) { phase = pi + 1; break; } }
    const kc = G.kcal || 2200, st = G.steps || 8000;
    const ph = PL.phases[phase - 1] || null;
    const out: DayPlan = {
      idx, inRange, week: wk, dow, phase, lab: T.LABS[k] || null, task: T.TASKS[k] || null, waistDay: d(k).getUTCDay() === ww,
      kcal: wk === T.TMAINT_W && (G.type || 'lose') === 'lose' ? kc + 500 : kc,
      protein: G.protein || 180,
      steps: ph && ph.steps ? ph.steps : phase === 1 ? st : phase === 2 ? st + 1000 : st + 2000,
      type: 'off', session: null, cardio: '',
    };
    if (!inRange) return out;
    const wkT = ph ? ph.weeks[wk % 2 === 0 && ph.weeks[1] ? 1 : 0] || ph.weeks[0] : null;
    const sl: Slot = (wkT && wkT[dow]) || { t: 'rest', c: '' };
    out.session = sl.t === 'lift' && LIFTS[sl.s] ? sl.s : null;
    out.cardio = sl.c || '';
    out.type = out.session ? 'lift' : sl.t === 'rest' ? 'rest' : 'cardio';
    return out;
  }

  function checkList(p: DayPlan, userChecks: UserCheck[] = [], hiddenChecks: Record<string, string | true> = {}, includeHidden = false): CheckItem[] {
    const list: (CheckItem & { _i?: number })[] = [];
    if (p.waistDay) list.push({ id: 'waist', w: 'Waking', t: 'Waist measurement', s: 'Navel level, before food or water, tape snug not tight' });
    if (p.dow === 6 && p.week % 4 === 0) list.push({ id: 'photos', w: 'Waking', t: 'Progress photos', s: 'Front, side, back, same light, same spot' });
    list.push({ id: 'water', w: 'All day', t: 'Water, about ' + trimNum(+(PROFILE.waterL ?? 0) || 3) + ' L', s: "Start early. Most people can't catch up after 6 pm." });
    list.push({ id: 'protein', w: 'Meals', t: (p.protein || G.protein || 120) + ' g protein', s: 'Protein before the carbs, every meal' });
    if (p.lab) list.push({ id: 'lab', w: 'Daytime', t: 'Book bloods', s: p.lab });
    if (p.task) list.push({ id: 'task', w: 'Daytime', t: 'Milestone', s: p.task });
    if (p.type === 'lift') {
      list.push({ id: 'mobility', w: 'Session', t: 'Mobility set', s: '5 min moving warm-up before the lift, 8 min held stretches after' });
      list.push({ id: 'train', w: 'Session', t: 'Lift: ' + NAMES[p.session!], s: 'Open Train and log weight and reps as you go' });
    } else if (p.type === 'cardio') {
      list.push({ id: 'train', w: 'Session', t: 'Cardio session', s: p.cardio });
      list.push({ id: 'mobility', w: 'After', t: 'Mobility set', s: '8 min of held stretches, while you are still warm' });
    } else {
      list.push({ id: 'mobility', w: 'Anytime', t: 'Mobility set', s: '8 min of held stretches' });
    }
    list.push({ id: 'sleep', w: 'Night', t: '7–8 hours in bed', s: 'Counts as much as the gym session' });
    userChecks.forEach((u) => {
      if (!u || !u.id) return;
      const hit = list.find((x) => x.id === u.id);
      if (hit) { if (u.t) hit.t = u.t; if (u.w) hit.w = u.w; if (u.s != null) hit.s = u.s; }
      else if (!u.builtinOnly) list.push({ id: u.id, w: u.w || '', t: u.t, s: u.s || '', custom: true });
    });
    list.forEach((c, i) => { c._i = i; });
    list.sort((a, b) => whenRank(a.w) - whenRank(b.w) || a._i! - b._i!);
    const clean = list.map(({ _i, ...c }) => c);
    return includeHidden ? clean : clean.filter((c) => !hiddenChecks[c.id]);
  }

  /** Planned set count from a scheme like "3 × 10-12". */
  const setCount = (scheme: string) => { const m = String(scheme || '').match(/(\d+)\s*×/); return m ? +m[1] : 3; };

  return { G, PROFILE, PL, LIFTS, NAMES, T, plan, checkList, setCount };
}
